import{_ as t,o as n,c as o,a5 as s}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"UC — Content Writting View","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-10-content-writting-view/spec.md","filePath":"feature/content-task-workflow/3-6-10-content-writting-view/spec.md"}'),a={name:"feature/content-task-workflow/3-6-10-content-writting-view/spec.md"};function i(r,e,c,l,d,p){return n(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="uc-—-content-writting-view" tabindex="-1">UC — Content Writting View <a class="header-anchor" href="#uc-—-content-writting-view" aria-label="Permalink to &quot;UC — Content Writting View&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.6.10</td></tr><tr><td>Feature</td><td>Content Writting View</td></tr><tr><td>Domain</td><td>Content &amp; Workflow (FR 3.6)</td></tr><tr><td>Role</td><td>CREATOR</td></tr><tr><td>Version</td><td>5.0 (V5 — Docs/Word hybrid UI redesign + presence/multi-cursor awareness + React Native mobile port, 2026-10-26; V4 — canvas-rendering + Yjs CRDT real-time sync over WebSocket, 2026-10-01)</td></tr><tr><td>Document Status</td><td>Implemented — minimal Task entity (not full FR 3.6.1), core + real-time sync + version history + presence live on web; mobile port (RN TextInput, not canvas) live with the same sync/formatting/version-history/preview feature set; see task.md for what&#39;s still pending</td></tr></tbody></table><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Write content the way Google Docs <strong>actually</strong> works (canvas-rendering, not an ordinary DOM-based rich-text editor), auto-convert fonts to the correct standard on publish, keep Content History/Version, and let multiple Creators edit the same content concurrently in real time via Operational Transformation (OT).</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As a Creator, I want to write content directly in the system, without having to copy it through an external tool to fix the font before posting. If a colleague has the same content open, I want to see their edits almost instantly without losing my own.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ul><li><strong>Canvas-based</strong> editor (mirrors the real Google Docs architecture — see §4) — supports basic formatting (bold, italic, list, emoji).</li><li><strong>Automatic font conversion on publish</strong> — solves the current pain point of having to copy through Unikey/Yantext before posting to social platforms.</li><li><strong>Content History/Version</strong>: every edit is stored as an operation log entry (not an overwritten snapshot), restorable to a prior snapshot point.</li><li><strong>Real-time collaborative editing</strong>: 2+ Creators with the same content open see each other&#39;s edits almost instantly, with neither side losing data (Operational Transformation).</li></ul><h2 id="_4-ui-ux" tabindex="-1">4. UI / UX <a class="header-anchor" href="#_4-ui-ux" aria-label="Permalink to &quot;4. UI / UX&quot;">​</a></h2><ul><li>Editor embedded in the Task Detail (Post type), with a Version History sidebar.</li><li><strong>Page chrome (V5, 2026-10-26)</strong>: the canvas sits on a white &quot;paper&quot; sheet (max-width 816px, matching a Docs/Word page at 96dpi) over a gray &quot;desk&quot; background, with a toolbar that toggles between a <strong>Docs mode</strong> (compact single-row icon bar) and a <strong>Ribbon mode</strong> (Word-style grouped icons with captions under each group) — purely visual, no change to the underlying edit operations or Yjs wiring.</li><li><strong>Presence (V5, 2026-10-26)</strong>: other Creators currently viewing/editing the document show as small colored avatar initials in the top status bar, and as a colored flag-with-name marker at their live caret position inside the editor (see <a href="./plan.html">plan.md</a> for the awareness-protocol design). Each peer&#39;s color is deterministic from their user ID (same color across sessions/devices).</li><li><strong>Rendering architecture: canvas-based (mirrors the real Google Docs), not an ordinary DOM/contentEditable editor:</strong><ul><li>Content is drawn pixel-accurately onto a <code>&lt;canvas&gt;</code> — no HTML tags are used to display the text. Reason: WYSIWYG fidelity for print/PDF, avoiding line-shift differences across browsers/devices/fonts.</li><li>A hidden <code>contenteditable</code>, pushed off-screen (e.g. <code>translateX(-10000px)</code>), captures keyboard/IME events (including Vietnamese input via Unikey/Telex) — it is never shown; it only receives input and forwards it into the canvas editor&#39;s internal state.</li><li>The blinking cursor is a <code>&lt;div&gt;</code> animated with CSS, positioned using pixel coordinates computed from the canvas text layout — not the browser&#39;s native cursor.</li><li>Text selection highlighting is also drawn by the canvas itself, not via the native <code>window.getSelection()</code>.</li><li>Virtualization: only the page(s) currently in the viewport get a canvas created/rendered; scrolling reuses existing canvases to draw the new page&#39;s content, keeping long documents light.</li><li>Accessibility: a parallel hidden DOM region (off-screen, <code>aria-live</code> or equivalent) holds the real text, since screen readers cannot read canvas pixels.</li></ul></li></ul><h2 id="_5-api-contract-implemented" tabindex="-1">5. API Contract (implemented) <a class="header-anchor" href="#_5-api-contract-implemented" aria-label="Permalink to &quot;5. API Contract (implemented)&quot;">​</a></h2><p>REST for the initial load, snapshot reporting, and version history/restore; STOMP WebSocket for real-time sync between Creators who have the same content open (see §7 Edge Cases).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/workspaces/{id}/tasks/{taskId}/content</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: { &quot;snapshot&quot;: &quot;&lt;base64 Yjs state|null&gt;&quot;, &quot;operationsSinceSnapshot&quot;: [&quot;&lt;base64 Yjs update&gt;&quot;, ...], &quot;sequenceNumber&quot; } }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>WS /ws/tasks?token=&lt;JWT&gt;  (STOMP over spring-boot-starter-websocket; JWT via query param, not header)</span></span>
<span class="line"><span>Client → Server: PUBLISH /app/tasks/{taskId}/content  { &quot;update&quot;: &quot;&lt;base64 Yjs update&gt;&quot; }</span></span>
<span class="line"><span>Server → SUBSCRIBE /topic/tasks/{taskId}/content: { &quot;update&quot;, &quot;sequenceNumber&quot;, &quot;editedBy&quot; }</span></span>
<span class="line"><span>// The server never decodes the update — it&#39;s an opaque Yjs CRDT blob (plan.md §6 direction B, not hand-written OT).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>POST /api/v1/workspaces/{id}/tasks/{taskId}/content/snapshot</span></span>
<span class="line"><span>Body: { &quot;yjsState&quot;: &quot;&lt;base64 Yjs state&gt;&quot;, &quot;atSequenceNumber&quot; }</span></span>
<span class="line"><span>// Client-reported: the server has no Yjs runtime to merge updates into a state itself.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Client → Server: PUBLISH /app/tasks/{taskId}/awareness  { &quot;update&quot;: &quot;&lt;base64 y-protocols/awareness update&gt;&quot; }</span></span>
<span class="line"><span>Server → SUBSCRIBE /topic/tasks/{taskId}/awareness: { &quot;update&quot; }</span></span>
<span class="line"><span>// Presence/multi-cursor (added V5, 2026-10-26): same opaque-blob posture as content — the server relays without</span></span>
<span class="line"><span>// decoding and, unlike content, never persists anything (awareness state is &quot;who&#39;s online + their cursor right</span></span>
<span class="line"><span>// now&quot;, not something a reload should restore). A silent client&#39;s state is cleared by y-protocols&#39; own built-in</span></span>
<span class="line"><span>// 30s outdated-state timeout on every other client, so no server-side cleanup job is needed.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GET /api/v1/workspaces/{id}/tasks/{taskId}/content/versions</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: [{ &quot;snapshotId&quot;, &quot;sequenceNumber&quot;, &quot;createdAt&quot;, &quot;editedBy&quot;, &quot;editedByName&quot; }] }</span></span>
<span class="line"><span>// newest first. editedBy/editedByName = last editor whose operation is included in the snapshot (null if unknown).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GET /api/v1/workspaces/{id}/tasks/{taskId}/content/versions/{snapshotId}</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: { &quot;snapshot&quot;: &quot;&lt;base64 Yjs state&gt;&quot;, &quot;operationsSinceSnapshot&quot;: [], &quot;sequenceNumber&quot; } }</span></span>
<span class="line"><span>// read-only; the client decodes it to text to render a diff against the previous version.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>POST /api/v1/workspaces/{id}/tasks/{taskId}/content/versions/{snapshotId}/restore</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: { &quot;snapshot&quot;: &quot;&lt;base64 Yjs state&gt;&quot;, &quot;operationsSinceSnapshot&quot;: [], &quot;sequenceNumber&quot; } }</span></span>
<span class="line"><span>// READ-ONLY on the server: returns the old state and writes nothing. A CRDT cannot rewind by merging an older state,</span></span>
<span class="line"><span>// so the client replaces the live Y.Text with the old content as a normal edit (delete + applyDelta); that update</span></span>
<span class="line"><span>// is persisted and broadcast over the WebSocket like any other, keeping the log append-only.</span></span></code></pre></div><p><strong>Snapshots</strong> are client-reported (<code>POST .../content/snapshot</code>): when the log since the last snapshot reaches 200 operations, <strong>or</strong> after 20 s without edits, <strong>or</strong> when the editor unmounts. The server ignores a report whose <code>atSequenceNumber</code> is not newer than the latest snapshot.</p><p><strong>Lists</strong> are literal text prefixes (<code>• </code>, <code>1. </code>) so the published text matches what is displayed; Enter inside an item continues the list and Enter on an empty item leaves it. <strong>Publish text</strong> (<code>toPublishText</code>) NFC-normalizes Vietnamese and renders bold/italic runs as Unicode Mathematical Sans-Serif letters; see <a href="./test.html">test.md</a> for the verified cases.</p><h2 id="_6-error-handling" tabindex="-1">6. Error Handling <a class="header-anchor" href="#_6-error-handling" aria-label="Permalink to &quot;6. Error Handling&quot;">​</a></h2><ul><li>Task is not of type <code>post</code> → 400 <code>INVALID_TASK_TYPE_FOR_CONTENT_WRITING</code>.</li><li>WebSocket handshake without a valid JWT → connection rejected with 401 (<code>WsJwtHandshakeInterceptor</code>).</li><li>STOMP SEND <code>/app/tasks/{id}/content</code> or SUBSCRIBE <code>/topic/tasks/{id}/content</code> by a user who is not an active MANAGER/CREATOR of the task&#39;s workspace, or for an unknown task → the frame is rejected with a STOMP ERROR (<code>ChatInboundChannelInterceptor.authorizeTask</code>); nothing is persisted or delivered.</li><li>Stale-sequence rejection (<code>STALE_SEQUENCE_NUMBER</code>) is defined as an error code but <strong>not yet wired to any check</strong> — there is no compaction job that prunes old operations in this implementation (<code>task_content_operations</code> only grows), so the condition it would guard against cannot currently occur.</li></ul><h2 id="_7-edge-cases" tabindex="-1">7. Edge Cases <a class="header-anchor" href="#_7-edge-cases" aria-label="Permalink to &quot;7. Edge Cases&quot;">​</a></h2><ul><li><p><strong>Two Creators editing the same content concurrently (e.g. QC + the original Creator both have edit rights) — resolved via Yjs CRDT merge, not locking or last-write-wins (implemented; plan.md §6 direction B, not hand-written OT):</strong></p><p>The real Google Docs does <strong>not</strong> save/sync a document as a text blob that gets overwritten on every save — it uses Operational Transformation (OT): a central <code>transform(opA, opB)</code> step reconciles concurrent edits. This implementation reaches the same outcome (nobody loses an edit, no lock needed) via a different algorithm: <strong>Yjs</strong>, a CRDT (Conflict-free Replicated Data Type) library. Each client mutates a local <code>Y.Doc</code>; Yjs updates merge automatically and commutatively on every client and the server — no central transform step is needed, which is also why the server never has to decode what an update contains (see §5&#39;s WS contract).</p><p>Google Docs&#39; real transport is Long Polling (an HTTP <code>bind</code> endpoint, for historical reasons dating back to 2006). This feature uses <strong>WebSocket</strong> (STOMP over <code>spring-boot-starter-websocket</code>) instead — the same real-time, bidirectional effect on more modern infrastructure.</p><p>Implementation details and the hand-written-OT vs. CRDT-library trade-off this decision was based on — see <a href="./plan.html#6-technical-risks">plan.md §6 Technical Risks</a>.</p></li><li><p><strong>Vietnamese IME through the off-screen hidden input</strong>: typing diacritics (Unikey, Telex, VNI) through the off-screen <code>contenteditable</code> must work correctly with <code>compositionstart</code>/<code>compositionupdate</code>/<code>compositionend</code> — raw keystrokes must not be forwarded into the canvas state before composition ends, or diacritics will render incorrectly. <strong>Implemented and browser-verified.</strong></p></li><li><p><strong>Offline / WebSocket disconnect mid-session</strong>: <strong>implemented.</strong> <code>useTaskContentSync</code> reconnects (<code>reconnectDelay: 3000</code>, with a fresh access token via <code>beforeConnect</code>). Edits typed while disconnected go into a queue that is also persisted in <code>localStorage</code> (<code>brandhub-content-pending:{taskId}</code>), so closing the tab does not lose them; the queue is flushed after reconnect (Yjs updates are idempotent, replay is safe). On every reconnect the client re-reads the content log (<code>GET .../content</code>) and merges updates broadcast while it was away.</p></li></ul><h2 id="_8-definition-of-done" tabindex="-1">8. Definition of Done <a class="header-anchor" href="#_8-definition-of-done" aria-label="Permalink to &quot;8. Definition of Done&quot;">​</a></h2><ul><li>The canvas editor renders correctly; input/cursor/selection work through the offscreen input; Vietnamese IME types diacritics correctly.</li><li>Font auto-conversion works correctly on publish.</li><li>Version History is stored (operation log + periodic snapshots) and restores correctly.</li><li>Two Creators with the same content open, editing concurrently over WebSocket, converge to the same result with no data loss (correct OT transform).</li><li>Screen readers can read the content through the hidden DOM layer that runs in parallel with the canvas.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Comment/suggestion mode (like Google Docs &quot;Suggesting&quot;) — not in the CSV.</li><li>Pagination/page breaks to A4 print standards — the CSV only requires writing content for social posts, not PDF export/printing.</li><li>Mobile: component-level RN tests and mobile E2E/device test (no <code>@testing-library/react-native</code> harness or Detox/Maestro in this project — not attempted). Image attachment, font/size/color/highlight/link controls, and a Docs/Ribbon toggle were initially deferred but completed the same day on request — see task.md item 16; mobile now has full feature parity with web except the live cursor-position marker (avatar-only presence — RN&#39;s <code>TextInput</code> has no per-character pixel coordinate API to place one).</li></ul><p>&gt; <strong>Superseded (was Out of Scope until V5, 2026-10-26)</strong>: showing avatars/colored cursors of who is typing where (multi-cursor presence UI) — now implemented on web; see §4 and §5&#39;s awareness endpoint. On mobile, presence shows as avatar initials only (no live cursor-position marker — not meaningful to render precisely against RN&#39;s TextInput, which doesn&#39;t expose per-character pixel coordinates the way canvas measurement does on web).</p><h2 id="ba-reference" tabindex="-1">BA Reference <a class="header-anchor" href="#ba-reference" aria-label="Permalink to &quot;BA Reference&quot;">​</a></h2><p><a href="./../../../BA/05-content-task-workflow.html">05-content-task-workflow.md</a></p>`,26)])])}const g=t(a,[["render",i]]);export{u as __pageData,g as default};
